style.css:
@-moz-document domain("open.spotify.com") {
/* =========================================================
       SPOTIFY — SILVERKING
       Neon Blue + Silver + Black + Anime Wallpaper
       ========================================================= */


    /* =========================================================
       COLORS
       ========================================================= */

    :root {
        --neon-blue: #00d9ff;
        --neon-blue-light: #63efff;
        --neon-blue-dark: #008fb3;

        --silver: #f1f4f8;
        --silver-light: #ffffff;
        --silver-dark: #aeb8c5;

        --black: #030507;
        --black-2: #070b10;

        --glass: rgba(3, 7, 12, 0.78);
        --glass-dark: rgba(2, 5, 9, 0.93);
    }


    /* =========================================================
       MAIN PAGE / WALLPAPER
       ========================================================= */

    html {
        background: #030507 !important;
    }

    body {
        background-color: #030507 !important;

        background-image:
            linear-gradient(
                90deg,
                rgba(0, 0, 0, 0.88) 0%,
                rgba(0, 3, 8, 0.74) 30%,
                rgba(0, 7, 15, 0.42) 62%,
                rgba(0, 3, 8, 0.62) 100%
            ),
            url(https://www.image2url.com/r2/default/images/1788410005199-f696f447-7493-4c1d-b93d-8d6d0df1bb07.jpg) !important;

        background-size: cover !important;
        background-position: center center !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;

        min-height: 100vh !important;
    }


    /* =========================================================
       MAKE SPOTIFY'S CONTAINERS TRANSPARENT
       SO THE WALLPAPER CAN SHOW THROUGH
       ========================================================= */

    #main,
    .Root,
    .Root__main-view,
    .Root__main-view-container,
    .Root__top-container,
    [data-testid="root"] {
        background: transparent !important;
    }


    /* =========================================================
       LEFT SIDEBAR
       ========================================================= */

    [data-testid="root-layout-left-sidebar"] {
        background:
            rgba(2, 5, 9, 0.94) !important;

        border-right:
            1px solid rgba(0, 217, 255, 0.20) !important;

        box-shadow:
            6px 0 30px rgba(0, 217, 255, 0.06) !important;
    }


    /* Sidebar links */

    nav a {
        color: var(--silver-dark) !important;

        transition:
            color 0.2s ease,
            text-shadow 0.2s ease !important;
    }

    nav a:hover {
        color: var(--neon-blue) !important;

        text-shadow:
            0 0 8px rgba(0, 217, 255, 0.55) !important;
    }


    /* Active sidebar item */

    nav a[aria-current="page"] {
        color: var(--silver-light) !important;

        text-shadow:
            0 0 8px rgba(0, 217, 255, 0.45) !important;
    }


    /* =========================================================
       MAIN CONTENT GLASS
       ========================================================= */

    .Root__main-view {
        background:
            rgba(2, 5, 10, 0.38) !important;
    }


    /* =========================================================
       TOP NAVIGATION
       ========================================================= */

    header,
    [data-testid="topbar"] {
        background:
            rgba(3, 6, 11, 0.72) !important;

        backdrop-filter:
            blur(12px) !important;

        -webkit-backdrop-filter:
            blur(12px) !important;

        border-bottom:
            1px solid rgba(0, 217, 255, 0.10) !important;
    }


    /* =========================================================
       SEARCH BAR
       ========================================================= */

    [data-testid="search-input"] {
        background:
            rgba(5, 10, 17, 0.88) !important;

        color:
            var(--silver) !important;

        border:
            1px solid rgba(0, 217, 255, 0.20) !important;

        border-radius:
            999px !important;

        box-shadow:
            inset 0 0 12px rgba(0, 217, 255, 0.03) !important;

        transition:
            border-color 0.2s ease,
            box-shadow 0.2s ease !important;
    }


    [data-testid="search-input"]:focus {
        border-color:
            var(--neon-blue) !important;

        box-shadow:
            0 0 12px rgba(0, 217, 255, 0.25),
            inset 0 0 10px rgba(0, 217, 255, 0.05) !important;
    }


    /* =========================================================
       TEXT
       ========================================================= */

    h1,
    h2,
    h3,
    h4 {
        color:
            var(--silver-light) !important;
    }


    /* Subdued text */

    [data-encore-id="text"][data-encore-internal-extract="true"] {
        color:
            var(--silver-dark) !important;
    }


    /* =========================================================
       CARDS
       ========================================================= */

    [data-testid="card"] {
        background:
            rgba(5, 10, 17, 0.68) !important;

        border:
            1px solid rgba(0, 217, 255, 0.07) !important;

        border-radius:
            10px !important;

        transition:
            transform 0.20s ease,
            background 0.20s ease,
            border-color 0.20s ease,
            box-shadow 0.20s ease !important;
    }


    [data-testid="card"]:hover {
        background:
            rgba(7, 15, 24, 0.88) !important;

        border-color:
            rgba(0, 217, 255, 0.42) !important;

        box-shadow:
            0 0 18px rgba(0, 217, 255, 0.12),
            inset 0 0 15px rgba(0, 217, 255, 0.025) !important;

        transform:
            translateY(-2px) !important;
    }


    /* =========================================================
       PLAY BUTTONS
       ========================================================= */

    [data-testid="play-button"] {
        background:
            var(--neon-blue) !important;

        color:
            #001018 !important;

        box-shadow:
            0 0 12px rgba(0, 217, 255, 0.50),
            0 0 28px rgba(0, 217, 255, 0.16) !important;

        transition:
            background 0.2s ease,
            box-shadow 0.2s ease,
            transform 0.2s ease !important;
    }


    [data-testid="play-button"]:hover {
        background:
            var(--neon-blue-light) !important;

        box-shadow:
            0 0 18px rgba(0, 217, 255, 0.75),
            0 0 40px rgba(0, 217, 255, 0.22) !important;

        transform:
            scale(1.04) !important;
    }


    /* =========================================================
       GENERAL BUTTONS
       ========================================================= */

    button {
        transition:
            color 0.2s ease,
            filter 0.2s ease !important;
    }


    button:hover {
        color:
            var(--neon-blue) !important;
    }


    /* =========================================================
       NOW PLAYING / BOTTOM PLAYER
       ========================================================= */

    [data-testid="now-playing-bar"] {
        background:
            rgba(2, 5, 9, 0.97) !important;

        border-top:
            1px solid rgba(0, 217, 255, 0.22) !important;

        box-shadow:
            0 -5px 30px rgba(0, 217, 255, 0.08) !important;
    }


    /* Player controls */

    [data-testid="control-button"] {
        color:
            var(--silver-dark) !important;

        transition:
            color 0.2s ease,
            filter 0.2s ease !important;
    }


    [data-testid="control-button"]:hover {
        color:
            var(--neon-blue) !important;

        filter:
            drop-shadow(
                0 0 5px rgba(0, 217, 255, 0.65)
            ) !important;
    }


    /* =========================================================
       PROGRESS BAR
       ========================================================= */

    [role="progressbar"] {
        --fg-color:
            var(--neon-blue) !important;
    }


    /* =========================================================
       SLIDERS
       ========================================================= */

    input[type="range"] {
        accent-color:
            var(--neon-blue) !important;
    }


    /* =========================================================
       VOLUME
       ========================================================= */

    [data-testid="volume-bar"] {
        accent-color:
            var(--neon-blue) !important;
    }


    /* =========================================================
       PLAYLISTS
       ========================================================= */

    [data-testid="playlist-page"] {
        background:
            transparent !important;
    }


    /* Playlist rows */

    [data-testid="tracklist-row"] {
        border-radius:
            6px !important;

        transition:
            background 0.15s ease !important;
    }


    [data-testid="tracklist-row"]:hover {
        background:
            rgba(0, 217, 255, 0.07) !important;
    }


    /* =========================================================
       ALBUM ART GLOW
       ========================================================= */

    img {
        transition:
            box-shadow 0.2s ease !important;
    }


    [data-testid="card"] img:hover {
        box-shadow:
            0 0 18px rgba(0, 217, 255, 0.18) !important;
    }


    /* =========================================================
       CONTEXT MENUS / POPUPS
       ========================================================= */

    [role="menu"],
    [role="dialog"] {
        background:
            rgba(5, 9, 15, 0.97) !important;

        border:
            1px solid rgba(0, 217, 255, 0.18) !important;

        box-shadow:
            0 10px 40px rgba(0, 0, 0, 0.60),
            0 0 20px rgba(0, 217, 255, 0.07) !important;
    }


    /* =========================================================
       HOVER EFFECT FOR MENU ITEMS
       ========================================================= */

    [role="menuitem"]:hover {
        background:
            rgba(0, 217, 255, 0.10) !important;

        color:
            var(--neon-blue-light) !important;
    }


    /* =========================================================
       SCROLLBAR
       ========================================================= */

    ::-webkit-scrollbar {
        width:
            8px !important;

        height:
            8px !important;
    }


    ::-webkit-scrollbar-track {
        background:
            rgba(0, 0, 0, 0.30) !important;
    }


    ::-webkit-scrollbar-thumb {
        background:
            rgba(0, 217, 255, 0.30) !important;

        border-radius:
            999px !important;
    }


    ::-webkit-scrollbar-thumb:hover {
        background:
            rgba(0, 217, 255, 0.70) !important;

        box-shadow:
            0 0 8px rgba(0, 217, 255, 0.45) !important;
    }


    /* =========================================================
       TEXT SELECTION
       ========================================================= */

    ::selection {
        background:
            rgba(0, 217, 255, 0.38) !important;

        color:
            #ffffff !important;
    }


    /* =========================================================
       NEON FOCUS
       ========================================================= */

    :focus-visible {
        outline:
            1px solid var(--neon-blue) !important;

        outline-offset:
            2px !important;

        box-shadow:
            0 0 8px rgba(0, 217, 255, 0.30) !important;
    }
}
